{"path": "src/components/TodoList.jsx", "content": "import { TodoItem } from './TodoItem.jsx'

export function TodoList({ todos, onToggle, onRemove, onClearCompleted }) {
  if (todos.length === 0) return <p>Nothing to do.</p>

  const activeCount = todos.filter((todo) => !todo.done).length
  const completedCount = todos.length - activeCount

  return (
    <>
      <ul>
        {todos.map((todo) => (
          <TodoItem key={todo.id} todo={todo} onToggle={onToggle} onRemove={onRemove} />
        ))}
      </ul>
      <p>{activeCount === 1 ? '1 item left' : `${activeCount} items left`}</p>
      <button type="button" onClick={onClearCompleted} disabled={completedCount === 0}>
        Clear completed
      </button>
    </>
  )
}
"}

